/* an anim activation sent over the network (SOCOM 1's DWARF; the arguments follow) */
class ZAnimNetworkPacket {
public:
    int packet_size;   // 0x0
    unsigned short anim_set_index;   // 0x4
    unsigned short anim_index;   // 0x6
};   // 0x8 bytes
