/* a node's saved state: one of 12 bytes per node reference a set saves (SOCOM 1's
 * CZAnimSetSave::Add makes the same; the type is in no DWARF, so its names are ours) -- the node,
 * which states were kept, and each one's index into the save's lists */
class _zanim_node_save {
public:
    CNode *node;   // 0x0
    unsigned int active : 1;   // 0x4: the node's activity, when kept
    unsigned int has_active : 1;
    unsigned int has_parent : 1;
    unsigned int has_translation : 1;
    unsigned int has_rotation : 1;
    unsigned int parent_index : 14;
    unsigned int translation_index : 14;   // 0x8
    unsigned int rotation_index : 14;
};   // 0xc bytes

/* a node's saved rotation: its matrix's three rows (Add's new of 36 bytes; ours) */
class _zanim_node_rotation {
public:
    CPnt3D x;   // 0x0
    CPnt3D y;   // 0xc
    CPnt3D z;   // 0x18
};   // 0x24 bytes

/* the node states a set restores: one save record per node reference, and the states the
 * records index (SOCOM 1's DWARF has the four vectors; their element types are read off Add,
 * Reset and the destructors -- the records and the rotations are deleted one by one) */
class CZAnimSetSave : public std::vector<_zanim_node_save *> {
public:
    void Reset(_zanim_node_save *save);
    void Add(_zanim_node_ref *ref);
    void Free();

    std::vector<CPnt3D> m_translationList;   // 0xc
    std::vector<_zanim_node_rotation *> m_rotationList;   // 0x18
    std::vector<CNode *> m_parentList;   // 0x24
};   // 0x30 bytes

enum LOD {LOW = 0, MEDIUM = 1, HIGH = 2};   // 1 byte(s)

class _zanim_cmd_hdr {
public:
    unsigned int data_type : 16;   // 0x0
    unsigned int quad_align : 1;   // 0x0
    unsigned int timeless : 1;   // 0x0
    unsigned int data_size : 14;   // 0x0
};   // 0x4 bytes

class _zsequence {
public:
    unsigned int name_index : 16;   // 0x0
    int loop_counter : 16;   // 0x0
    unsigned int paused : 1;   // 0x4
    unsigned int activation : 7;   // 0x4
    unsigned int state : 8;   // 0x4
    unsigned int cmd_state : 8;   // 0x4
    unsigned int m_IF_NestLevel : 8;   // 0x4
    char* cmd_pc;   // 0x8
    int seq_data_size;   // 0xc
    float seq_timer;   // 0x10
    float cmd_timer;   // 0x14
    float loop_timer;   // 0x18
};   // 0x1c bytes

/* a ZRDR value (SOCOM 1's DWARF): a typed word -- 3 a string, 4 an array of length values */
struct _zrdr {
    unsigned int type : 8;   // 0x0
    unsigned int isclone : 1;   // 0x0
    unsigned int packed : 1;   // 0x0
    unsigned int unused : 6;   // 0x0
    unsigned int length : 16;   // 0x0
    union {
        float real;
        int integer;
        char *string;
        _zrdr *array;
    };   // 0x4

    /* (ours; the count unsigned: LoadNodeNames' walk compares with sltu) */
    unsigned int Count() { return type == 4 ? length : 0; }
    _zrdr *Item(int i) { return i < Count() ? &array[i] : 0; }
    char *String() { return type == 3 ? string : 0; }
    /* a number: a real as it is, an integer converted, anything else 0 (ours) */
    float Real()
    {
        if (type == 2)
            return real;
        else if (type == 1)
            return (float)integer;
        else
            return 0.0f;
    }
};   // 0x8 bytes

/* SOCOM 1's zrdr_findtag, matched in its own unit under its address's name */
extern "C" _zrdr *func_0032F0D0(_zrdr *rdr, const char *tag);
/* data appended to a command, which may move: the command given back (SOCOM 1's) */
_zanim_cmd_hdr *zAnimCmdAddData(_zanim_cmd_hdr *hdr, void *data, int size);

/* the wildcard search over node names (anim_main.cpp) */
const char *ZAnimWildcardApply(const char *name);
const char *ZAnimWildcardNext();
const char *ZAnimWildcardInit(char *pattern);

/* a command's id, as a file's records carry it: its index in its set, and the set (a halfword:
 * CmdTick copies it with lhu/sh) */
union _zanim_cmd_id {
    unsigned short id;
    struct {
        unsigned char index;
        unsigned char set;
    } b;
};

/* a registered command (CZAnimMain::AddCmd): its name and four handlers, 0x14 bytes */
struct zanim_cmd {
    char *name;
    _zanim_cmd_id id;               /* its own (GetCmd fills it) */
    unsigned short pad;
    void (*begin)(_zanim_cmd_hdr *hdr);
    bool (*tick)(_zanim_cmd_hdr *hdr, float *dT);
    void (*end)(_zanim_cmd_hdr *hdr);
};


class _zanim_cmd_set {
public:
    char *name;   // 0x0
    int count;   // 0x4
    zanim_cmd *cmd_list;   // 0x8
};

